import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long even = 0, odd = 0;
        boolean hasOdd = false; // odd sum reachable yet?
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            if (v % 2 != 0) {
                long ne = Math.max(even, hasOdd ? odd + v : even);
                long no = Math.max(hasOdd ? odd : v, even + v);
                even = ne;
                odd = no;
                hasOdd = true;
            } else {
                even = Math.max(even, even + v);
                if (hasOdd) odd = Math.max(odd, odd + v);
            }
        }
        System.out.println(even);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := int(nextInt())
	var even, odd int64
	hasOdd := false // odd sum reachable yet?
	for i := 0; i < n; i++ {
		v := nextInt()
		if v%2 != 0 {
			ne := even
			if hasOdd {
				ne = max(even, odd+v)
			}
			no := even + v
			if hasOdd {
				no = max(odd, no)
			} else {
				no = max(v, no)
			}
			even, odd, hasOdd = ne, no, true
		} else {
			even = max(even, even+v)
			if hasOdd {
				odd = max(odd, odd+v)
			}
		}
	}
	w.WriteString(strconv.FormatInt(even, 10) + "\n")
}
